//! The bundled registry data: `src/data/*.json`, generated by
//! `scripts/build-data.mjs` from mzizi-registry at the ref pinned in
//! `scripts/registry-ref.json`. The same files the TypeScript Worker bundles,
//! embedded in the wasm module and parsed once per isolate, on first use.
//! Nothing is fetched at request time and nothing comes from a database.

use std::collections::HashMap;
use std::sync::OnceLock;

use indexmap::IndexMap;
use mzizi_api_types::{AstroDocument, ComponentDocs, Helix, ItemFile, Object, RegistryItem};
use serde::Deserialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

macro_rules! bundled {
    ($file:literal) => {
        include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../src/data/",
            $file
        ))
    };
}

fn parse<T: DeserializeOwned>(file: &str, text: &str) -> T {
    serde_json::from_str(text).unwrap_or_else(|e| panic!("src/data/{file}: {e}"))
}

macro_rules! lazy {
    ($(#[$m:meta])* $name:ident: $ty:ty = $file:literal) => {
        $(#[$m])*
        pub fn $name() -> &'static $ty {
            static CELL: OnceLock<$ty> = OnceLock::new();
            CELL.get_or_init(|| parse($file, bundled!($file)))
        }
    };
}

/// `meta.json`: the pin, the rename map, the crate git URL and the OpenAPI YAML.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Meta {
    #[serde(rename = "ref")]
    pub registry_ref: String,
    /// `nyuchi-*` → `mzizi-*` component renames (mzizi-registry lib/component-renames.json).
    pub renames: IndexMap<String, String>,
    /// mzizi-registry `CRATE_GIT`.
    pub crate_git: String,
    pub openapi_yaml: String,
}

/// One entry of `sources.json`: the item's primary source and its `.rs`.
#[derive(Debug, Deserialize)]
pub struct SourcePair {
    pub primary: Option<String>,
    pub rs: Option<String>,
}

/// `helix.json`.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HelixFile {
    pub model: Helix,
    pub node_counts: Object,
}

/// `changelog.json`.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Changelog {
    pub entries: Vec<Value>,
    pub by_version: HashMap<String, Vec<Value>>,
}

/// `skills.json`: the pinned `@nyuchi/mzizi-skills` bundle.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Skills {
    pub list: Vec<Value>,
    pub by_name: HashMap<String, Value>,
    pub names: Vec<String>,
    pub version: Value,
}

lazy!(
    /// Every registry item, in registry order.
    components: Vec<RegistryItem> = "components.json"
);
lazy!(meta: Meta = "meta.json");
lazy!(sources: HashMap<String, SourcePair> = "sources.json");
lazy!(
    /// The base64 files of each binary-only item.
    binary: HashMap<String, Vec<ItemFile>> = "binary.json"
);
lazy!(astro: HashMap<String, AstroDocument> = "astro.json");
lazy!(helix: HelixFile = "helix.json");
lazy!(changelog: Changelog = "changelog.json");
lazy!(doctrine: Object = "doctrine.json");
lazy!(skills: Skills = "skills.json");
lazy!(
    /// Sample records by type, in the file's order (`Object.keys` order).
    samples: IndexMap<String, Vec<Value>> = "samples.json"
);
lazy!(brand: Object = "brand.json");
lazy!(component_docs: HashMap<String, ComponentDocs> = "component-docs.json");
lazy!(ai_instruction_index: HashMap<String, usize> = "ai-instruction-index.json");

/// Item positions by name.
fn by_name() -> &'static HashMap<&'static str, usize> {
    static CELL: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    CELL.get_or_init(|| {
        let mut map = HashMap::new();
        for (i, c) in components().iter().enumerate() {
            // `new Map(entries)`: a later duplicate wins.
            map.insert(c.name.as_str(), i);
        }
        map
    })
}

/// lib/registry.ts `readComponent`: by name, then by the name it was renamed from.
pub fn read_component(name: &str) -> Option<&'static RegistryItem> {
    let index = by_name().get(name).or_else(|| {
        meta()
            .renames
            .get(name)
            .and_then(|n| by_name().get(n.as_str()))
    })?;
    components().get(*index)
}

/// Which source of an item.
#[derive(Debug, Clone, Copy)]
pub enum SourceKind {
    Primary,
    Rs,
}

/// lib/registry-source.ts `readComponentSource` / `readComponentSourceFor(name, "rs")`.
pub fn read_source(name: &str, kind: SourceKind) -> Option<&'static str> {
    let pair = sources().get(name)?;
    match kind {
        SourceKind::Primary => pair.primary.as_deref(),
        SourceKind::Rs => pair.rs.as_deref(),
    }
}

/// Every name `/v1/astro/{name}` serves, sorted.
pub fn astro_names() -> &'static [String] {
    static CELL: OnceLock<Vec<String>> = OnceLock::new();
    CELL.get_or_init(|| {
        let mut names: Vec<String> = astro().keys().cloned().collect();
        // JS's default sort compares UTF-16 code units.
        names.sort_by(|a, b| a.encode_utf16().cmp(b.encode_utf16()));
        names
    })
}

/// lib/db `getAiInstruction(key) ?? getAiInstructionByTarget(key)`.
pub fn read_ai_instruction(key: &str) -> Option<&'static Value> {
    let index = *ai_instruction_index().get(key)?;
    doctrine().get("aiInstructions")?.as_array()?.get(index)
}

/// `X-Mzizi-Source`: identifies this Worker's answers and the registry commit.
pub fn source_header() -> &'static str {
    static CELL: OnceLock<String> = OnceLock::new();
    CELL.get_or_init(|| {
        let r = &meta().registry_ref;
        let short: String = r.chars().take(12).collect();
        format!("mzizi-api-gateway; registry={short}")
    })
}
